import{_ as o,o as r,c as s,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"2019-08-05 :: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2019-08-05 :: Ceph Orchestration Meeting","date":"2019-08-05T00:00:00.000Z","updated":"2019-08-12T00:00:00.000Z","tags":["Ceph","Orchestration","Distributed Storage","Kubernetes","Cloud Computing"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-08-05_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2019/2019-08-05_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780460162000}'),e={name:"posts/2019/2019-08-05_-_-_Ceph_Orchestration_Meeting.md"};function i(g,t,l,a,p,_){return r(),s("div",null,[...t[0]||(t[0]=[n('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月某日</p><p><strong>参会人员</strong>： Orchestra团队成员</p><p><strong>会议主题</strong>： Orchestra项目进展及讨论</p><p><strong>会议内容</strong>：</p><p><strong>一、会议改进建议</strong></p><ol><li><strong>会议议程</strong>： 团队成员对现有的会议议程表示满意，建议继续使用Pet或Google Doc等工具创建议程，以提高会议效率。</li><li><strong>参会人员</strong>： 建议邀请更多外部人员参与会议，例如来自欧洲或亚太地区的团队成员。</li></ol><p><strong>二、项目进展</strong></p><ol><li><strong>Noah的PR</strong>： 关于Mons运行Monzon的PR已合并。</li><li><strong>Peavey的PR</strong>： 已合并，需要指定持久卷声明模板，Mons将启动。</li><li><strong>PBS的PR</strong>： 希望本周完成，完成后只剩下收集日志和崩溃转储。</li><li><strong>Orchestrator模块</strong>： 讨论了如何在外部存储类中部署OSD，以及是否需要为Kubernetes环境提供特定的设置。</li><li><strong>CR验证PR</strong>： 使用CRD验证生成API代码，发现了一些未实现或已删除的功能。</li><li><strong>Rook PR</strong>： 发现了一个与schema相关的失败，需要进一步调查。</li><li><strong>事件记录</strong>： 讨论了将事件记录到Rook的问题，以及是否应将其与Orchestrator相关联。</li><li><strong>集群本地存储</strong>： 在使用Portman部署集群本地存储时遇到了困难，需要进一步调查。</li><li><strong>Isis和NFS</strong>： 对Isis和NFS进行了一些调查和修复。</li></ol><p><strong>三、行动计划</strong></p><ol><li><strong>邀请外部人员</strong>： 尝试邀请来自欧洲或亚太地区的团队成员参加下周三的会议。</li><li><strong>Rook PR调查</strong>： 进一步调查Rook PR中的schema失败。</li><li><strong>事件记录</strong>： 进一步调查将事件记录到Rook的问题。</li><li><strong>集群本地存储</strong>： 解决集群本地存储部署中的问题。</li><li><strong>Isis和NFS修复</strong>： 完成Isis和NFS的修复。</li></ol><p><strong>四、其他事项</strong></p><ol><li><strong>DNS使用</strong>： 讨论了在Kubernetes中使用DNS代替IP地址的问题，以解决一些部署问题。</li><li><strong>Monitor身份</strong>： 讨论了Monitor的身份问题，以及是否需要更改Monitor ID。</li></ol><p><strong>五、会议总结</strong></p><p>本次会议讨论了Orchestrator项目的进展，包括各个PR的状态、与Kubernetes和其他存储技术的整合、以及遇到了的技术挑战。团队还讨论了会议改进建议，并计划邀请更多外部人员参与讨论。</p>',15)])])}const d=o(e,[["render",i]]);export{h as __pageData,d as default};
